import java.util.Arrays;
import java.util.List;

public class ChangeCalculatorManualCheck {
    private static int checks = 0;

    public static void main(String[] args) {
        check(new ChangeCalculator(Arrays.asList(1, 5, 10, 25, 100)).computeMostEfficientChange(25),
                Arrays.asList(25));
        check(new ChangeCalculator(Arrays.asList(1, 5, 10, 25, 100)).computeMostEfficientChange(15),
                Arrays.asList(5, 10));
        check(new ChangeCalculator(Arrays.asList(1, 4, 15, 20, 50)).computeMostEfficientChange(23),
                Arrays.asList(4, 4, 15));
        check(new ChangeCalculator(Arrays.asList(1, 5, 10, 21, 25)).computeMostEfficientChange(63),
                Arrays.asList(21, 21, 21));
        check(new ChangeCalculator(Arrays.asList(1, 2, 5, 10, 20, 50, 100)).computeMostEfficientChange(999),
                Arrays.asList(2, 2, 5, 20, 20, 50, 100, 100, 100, 100, 100, 100, 100, 100, 100));
        check(new ChangeCalculator(Arrays.asList(2, 5, 10, 20, 50)).computeMostEfficientChange(21),
                Arrays.asList(2, 2, 2, 5, 10));
        check(new ChangeCalculator(Arrays.asList(4, 5)).computeMostEfficientChange(27),
                Arrays.asList(4, 4, 4, 5, 5, 5));
        check(new ChangeCalculator(Arrays.asList(1, 10, 11)).computeMostEfficientChange(20),
                Arrays.asList(10, 10));
        check(new ChangeCalculator(Arrays.asList(1, 5, 10, 21, 25)).computeMostEfficientChange(0),
                Arrays.asList());

        final ChangeCalculator smallCoins = new ChangeCalculator(Arrays.asList(5, 10));
        expectIllegalArgument(() -> smallCoins.computeMostEfficientChange(3),
                "The total 3 cannot be represented in the given currency.");
        expectIllegalArgument(() -> smallCoins.computeMostEfficientChange(94),
                "The total 94 cannot be represented in the given currency.");
        expectIllegalArgument(() -> new ChangeCalculator(Arrays.asList(1, 2, 5)).computeMostEfficientChange(-5),
                "Negative totals are not allowed.");

        System.out.println("All " + checks + " manual checks passed.");
    }

    private static void check(List<Integer> actual, List<Integer> expected) {
        checks++;
        if (!actual.equals(expected)) {
            throw new AssertionError("Expected " + expected + " but got " + actual);
        }
    }

    private static void expectIllegalArgument(Runnable action, String expectedMessage) {
        checks++;
        try {
            action.run();
            throw new AssertionError("Expected IllegalArgumentException with message: " + expectedMessage);
        } catch (IllegalArgumentException e) {
            if (!expectedMessage.equals(e.getMessage())) {
                throw new AssertionError("Expected message " + expectedMessage + " but got " + e.getMessage());
            }
        }
    }
}
